// The code sync anchors, read the same way by the app, the Cloud Functions and the rabbinatix CLI (assistant-and-cli-plan.md
// § 4). In any language's comment:
//   <comment> FDD:LOGIC-AUTH-LOGIN-001 r9 Sign in        above the function that implements a logic, at that revision
//   <comment> FDD:NODE-AUTH-LOGIN-017 Validate input     above one of its steps
//   <comment> Generated by Rabbinatix · logic LOGIC-… v1.3.0 (r12) · codegen … · sha256:… · do not edit   (first line)
//   <comment> FDD:SCREEN-WEB-LOGIN-001 r4 Login         a screen (or LAYOUT-…) built by hand, at that revision
//   data-key="WIDGET-…" in markup, or <comment> FDD:WIDGET-…   one of its widgets
// A one-line block comment works too (`/* FDD:… */`, `{/* FDD:… */}` in JSX, `(* FDD:… *)`, `<!-- FDD:… -->`).
import { LANGUAGES } from './languages';

const esc = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const LINE = [...new Set([...LANGUAGES.flatMap((l) => l.comments.line), '<!--'])].sort((a, b) => b.length - a.length);
const BLOCK_CLOSE = [...new Set([...LANGUAGES.flatMap((l) => l.comments.block.map((b) => b[1])), '-->'])].sort((a, b) => b.length - a.length);
const BLOCK_OPEN = [...new Set(LANGUAGES.flatMap((l) => l.comments.block.map((b) => b[0])))].sort((a, b) => b.length - a.length);
/** any comment opener, then exactly one space */
const OPEN = `(?:${[...LINE, ...BLOCK_OPEN].map(esc).join('|')}) `;
/** a block comment's close at the end, dropped from the title */
const CLOSE = `(?:\\s*(?:${BLOCK_CLOSE.map(esc).join('|')}))?\\s*$`;

const LOGIC_RE = new RegExp(`^\\s*${OPEN}FDD:(LOGIC-[A-Z0-9-]+) r(\\d+)(?: (.*?))?${CLOSE}`);
const NODE_RE = new RegExp(`^\\s*${OPEN}FDD:(NODE-[A-Z0-9-]+)\\+?(?: (.*?))?${CLOSE}`);
/** the generated header names its logic, then its revision: `v1.3.0 (r12)`, `(r3 + unsaved)`, or `r12` with no version
 *  (files generated before the rename say Flow Weaver or ContractMap) */
const STAMP_RE = new RegExp(`^\\s*${OPEN}Generated by (?:Rabbinatix|Flow Weaver|ContractMap)\\b.*?\\blogic (LOGIC-[A-Z0-9-]+)\\b(?:[^·]*?\\br(\\d+)\\b)?`);

/** screens and layouts (screen-builder-plan.md Phase 6); JSX wraps its comment in braces */
const SCREEN_RE = new RegExp(`^\\s*\\{?${OPEN}FDD:((?:SCREEN|LAYOUT)-[A-Z0-9-]+) r(\\d+)(?: (.*?))?(?:\\s*(?:${BLOCK_CLOSE.map(esc).join('|')})\\}?)?\\s*$`);
/** the first line of a file the screen export wrote: `Generated by Rabbinatix · screen SCREEN-… r4 · screens 1.0.0 · …` */
const SCREEN_STAMP_RE = /Generated by Rabbinatix · (?:screen|layout) ((?:SCREEN|LAYOUT)-[A-Z0-9-]+) r(\d+)/;
/** a widget in markup (`data-key="WIDGET-…"`) or a comment (`FDD:WIDGET-…`) */
const WIDGET_RE = /data-key="(WIDGET-[A-Z0-9-]+)"|FDD:(WIDGET-[A-Z0-9-]+)/g;

export interface CodeAnchors {
  /** the logic this file implements: `FDD:LOGIC-…` lines, or the generated header (revision when it says one) */
  logic: { key: string; revision?: number; line: number; title?: string; generated: boolean }[];
  nodes: { key: string; line: number; title?: string }[];
  /** screens and layouts: `FDD:SCREEN-… rN` lines or the screen export's header; only when there are some */
  screens?: { key: string; revision: number; line: number; title?: string; generated: boolean }[];
  /** widgets: `data-key="WIDGET-…"` in markup or `FDD:WIDGET-…` comments; only when there are some */
  widgets?: { key: string; line: number }[];
}

/** the anchors in a source file (lines 1-based) */
export function readAnchors(content: string): CodeAnchors {
  const out: CodeAnchors = { logic: [], nodes: [] };
  content.split(/\r?\n/).forEach((text, i) => {
    const line = i + 1;
    const h = i === 0 ? SCREEN_STAMP_RE.exec(text) : null;
    if (h) return void (out.screens ??= []).push({ key: h[1], revision: +h[2], line, generated: true });
    const sc = SCREEN_RE.exec(text);
    if (sc) return void (out.screens ??= []).push({ key: sc[1], revision: +sc[2], line, ...(sc[3]?.trim() ? { title: sc[3].trim() } : {}), generated: false });
    for (const m of text.matchAll(WIDGET_RE)) (out.widgets ??= []).push({ key: m[1] ?? m[2], line });
    const s = i === 0 ? STAMP_RE.exec(text) : null;
    if (s) return void out.logic.push({ key: s[1], ...(s[2] ? { revision: +s[2] } : {}), line, generated: true });
    const l = LOGIC_RE.exec(text);
    if (l) return void out.logic.push({ key: l[1], revision: +l[2], line, ...(l[3]?.trim() ? { title: l[3].trim() } : {}), generated: false });
    const n = NODE_RE.exec(text);
    if (n) out.nodes.push({ key: n[1], line, ...(n[2]?.trim() ? { title: n[2].trim() } : {}) });
  });
  return out;
}

/** the anchor line for a logic in a file's comment: `comment` from detect.ts commentFor / lineCommentOf */
export const logicAnchorLine = (comment: [string, string], key: string, revision: number, title?: string) =>
  `${comment[0]} FDD:${key} r${revision}${title ? ` ${title}` : ''}${comment[1]}`;

/** what one search finds every anchor with, in every language */
export const ANCHOR_GREP = 'FDD:|Generated by Rabbinatix|data-key="WIDGET-';
